nodes.raw:
help: ## Show available targets
	@grep -hE '^[a-zA-Z_-]+:.*?## ' $(MAKEFILE_LIST) \
	  | awk 'BEGIN{FS=":.*?## "}{printf "  \033[36m%-24s\033[0m %s\n", $$1, $$2}'

doctor: ## bstack primitive-contract compliance report (needs bstack; always exits 0)
	$(REQUIRE_BSTACK)
	@bash "$(BSTACK)/scripts/doctor.sh"

bstack-check: ## Harness validation — doctor in strict mode (needs bstack; non-zero on gap)
	$(REQUIRE_BSTACK)
	@bash "$(BSTACK)/scripts/doctor.sh" --strict

bstack-l3-trust: bstack-primitive-lint ## L3 trust-gate pack (G-L3-1; G-L3-2 scoped out — see note)
	@echo "[bstack-l3-trust] G-L3-1 primitive-lint passed."
	@echo "[bstack-l3-trust] G-L3-2 rule-of-three not run: no primitives are promoted in this repo."
	@echo "[bstack-l3-trust] L3 trust gates passed — governance change is structurally valid."

- name: fixture recomputes
  if: matrix.os == 'ubuntu-latest'
  run: |
    bun -e '
      import { groundingRatio } from "./skills/keel/schemas/keel.ts";
      const r = await Bun.file("tests/fixtures/report.sample.json").json();
      const g = groundingRatio(r.verdicts);
      if (JSON.stringify(g) !== JSON.stringify(r.grounding)) {
        throw new Error("stored grounding disagrees with a recomputation");
      }
      const naked = r.verdicts.filter((v) => !v.writeBoundary?.argument?.trim());
      if (naked.length) {
        throw new Error(naked.length + " verdict(s) carry no argument — a class without its causal path is an unaccountable green check");
      }
      console.log("fixture OK — ratio", g.ratio.toFixed(4), "over", r.verdicts.length, "verdicts");
    '

- name: self-measurement is current
  if: matrix.os == 'ubuntu-latest'
  run: |
    bun skills/keel/scripts/gather.ts . --json > /tmp/keel-nodes-now.json
    bun -e '
      const tally = (ns) => ns.reduce((m, n) => {
        const k = `${n.source.split(":")[0]}|${n.kind}|${n.name}`;
        return m.set(k, (m.get(k) ?? 0) + 1);
      }, new Map());
      const now = tally(await Bun.file("/tmp/keel-nodes-now.json").json());
      const report = await Bun.file("reports/keel-current.json").json();
      const then = tally(report.nodes);
      const drift = [];
      for (const k of new Set([...now.keys(), ...then.keys()])) {
        const a = now.get(k) ?? 0, b = then.get(k) ?? 0;
        if (a !== b) drift.push(`  ${a > b ? "+" : "-"} ${k}  (measured ${b}, now ${a})`);
      }
      if (drift.length) {
        for (const d of drift.sort()) console.error(d);
        throw new Error(
          `the verification surface changed since reports/keel-current.json was measured ` +
            `at ${report.revision.slice(0, 7)} — ${drift.length} edge(s) differ. Re-measure ` +
            `with keel and commit the report, or move the baseline deliberately.`,
        );
      }
      const total = [...then.values()].reduce((a, b) => a + b, 0);
      console.log(`self-measurement current — ${total} edges, unchanged since ${report.revision.slice(0, 7)}`);
    '

- name: Control gate blocks and allows correctly
  run: |
    set -euo pipefail
    run_gate() { printf '%s' "$1" | bash scripts/control-gate-hook.sh >/dev/null 2>&1; echo $?; }

    blocked=$(run_gate '{"tool_name":"Bash","tool_input":{"command":"git push --force origin main"}}')
    [ "$blocked" = "2" ] || { echo "FAIL: force-push not blocked (exit $blocked)"; exit 1; }
    echo "ok: force-push blocked"

    allowed=$(run_gate '{"tool_name":"Bash","tool_input":{"command":"git push origin main"}}')
    [ "$allowed" = "0" ] || { echo "FAIL: ordinary push blocked (exit $allowed)"; exit 1; }
    echo "ok: ordinary push allowed"
